## Tests for: `isAdult` (src/age.js)

**Scenarios covered:**
- [ ] Boundary: age exactly 18 → spec says adult, code uses strict `>` (bug candidate)
- [ ] Boundary: age 17 (just under), 19 (just over)
- [ ] Boundary: age 0, negative age, Number.MAX_SAFE_INTEGER
- [ ] Error: `null`, `undefined`, `NaN`, boolean, object/array passed instead of number
- [ ] Error: numeric string coercion (`"20"`, `"abc"`) — silent type coercion
- [ ] Happy path: clearly-adult and clearly-minor ages (confirmation, last)

```js
// test/age.test.js
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { isAdult } from '../src/age.js';

describe('isAdult', () => {
  describe('boundary conditions', () => {
    it('should return true when age is exactly 18 (spec: 18 or over is adult)', () => {
      // Arrange
      const age = 18;
      // Act
      const result = isAdult(age);
      // Assert
      assert.equal(result, true, 'age 18 must be classified as adult per spec "18 or over is an adult"');
    });

    it('should return true when age is 19 (just over threshold)', () => {
      const age = 19;
      const result = isAdult(age);
      assert.equal(result, true);
    });

    it('should return false when age is 17 (just under threshold)', () => {
      const age = 17;
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should return false when age is 0', () => {
      const age = 0;
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should return false when age is negative', () => {
      const age = -5;
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should return true when age is an extremely large number', () => {
      const age = Number.MAX_SAFE_INTEGER;
      const result = isAdult(age);
      assert.equal(result, true);
    });
  });

  describe('invalid / adversarial input', () => {
    it('should not silently misclassify when age is null', () => {
      // null coerces to 0 in `>` comparison — returns false with no error,
      // masking the fact that no real age was supplied.
      const age = null;
      const result = isAdult(age);
      assert.equal(result, false, 'documents current silent-coercion behavior; see handoff re: missing input validation');
    });

    it('should not silently misclassify when age is undefined', () => {
      const age = undefined;
      const result = isAdult(age);
      assert.equal(result, false, 'undefined > 18 is NaN comparison, always false');
    });

    it('should not silently misclassify when age is NaN', () => {
      const age = NaN;
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should not silently misclassify when age is a boolean', () => {
      const age = true; // coerces to 1
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should not silently misclassify when age is a plain object', () => {
      const age = {};
      const result = isAdult(age);
      assert.equal(result, false);
    });

    it('should not accept a numeric string as a valid age (type coercion hole)', () => {
      // "20" > 18 triggers JS numeric coercion and returns true despite
      // being a string, not a number — no type check at the boundary.
      const age = '20';
      const result = isAdult(age);
      assert.equal(result, true, 'documents current coercion behavior; flagged as type-safety gap');
    });

    it('should return false when age is a non-numeric string', () => {
      const age = 'abc';
      const result = isAdult(age);
      assert.equal(result, false);
    });
  });

  describe('happy path (confirmation only)', () => {
    it('should return true when age is well above 18', () => {
      const age = 25;
      const result = isAdult(age);
      assert.equal(result, true);
    });

    it('should return false when age is well below 18', () => {
      const age = 10;
      const result = isAdult(age);
      assert.equal(result, false);
    });
  });
});
```

**Coverage added:** Single-branch comparison function — all boundary values around the `18` threshold, non-numeric/nullish inputs, and type-coercion edge cases. No external dependencies, no state, no concurrency surface to cover (pure stateless function).

